package com.sigaa.controller;
import com.sigaa.dto.*; import com.sigaa.model.AuditLog; import com.sigaa.repository.UsuarioUnidadRepository; import com.sigaa.service.GrupoService; import com.sigaa.service.ParticipantePolicy; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/grupos") public class GrupoController {
 private final GrupoService service; private final UsuarioUnidadRepository usuarioUnidades; public GrupoController(GrupoService s, UsuarioUnidadRepository u){service=s;usuarioUnidades=u;}
 @GetMapping @PreAuthorize("hasAuthority('Grupos:Ver')") public List<GrupoResponse> listar(@RequestParam(required=false) String q,@RequestParam(required=false) String estado,@RequestParam(required=false) Long unidadId){return service.listar(q,estado,unidadId);}
 @GetMapping("/estadisticas") @PreAuthorize("hasAuthority('Grupos:Ver')") public Map<String,Long> estadisticas(){return service.estadisticas();}
 @GetMapping("/unidades") @PreAuthorize("hasAuthority('Grupos:Ver')") public List<com.sigaa.model.Unidad> unidades(){return service.unidadesVisibles();}
 @GetMapping("/{id}") @PreAuthorize("hasAuthority('Grupos:Ver')") public GrupoResponse obtener(@PathVariable Long id){return service.obtener(id);}
 @GetMapping("/{id}/resumen") @PreAuthorize("hasAuthority('Grupos:Ver')") public Map<String,Object> resumen(@PathVariable Long id){return service.resumen(id);}
 @GetMapping("/{id}/tareas") @PreAuthorize("hasAuthority('Grupos:Ver')") public List<Map<String,Object>> tareas(@PathVariable Long id){return service.tareas(id);}
 @GetMapping("/{id}/archivos") @PreAuthorize("hasAuthority('Grupos:Ver')") public List<Map<String,Object>> archivos(@PathVariable Long id){return service.archivos(id);}
 @GetMapping("/{id}/mensajes") @PreAuthorize("hasAuthority('Grupos:Ver')") public org.springframework.data.domain.Page<GrupoMensajeResponse> mensajes(@PathVariable Long id,@RequestParam(defaultValue="0") int pagina,@RequestParam(defaultValue="50") int tamano){return service.mensajes(id,pagina,tamano);}
 @PostMapping("/{id}/mensajes") @PreAuthorize("hasAuthority('Grupos:Ver')") public ResponseEntity<GrupoMensajeResponse> enviarMensaje(@PathVariable Long id,@Valid @RequestBody GrupoMensajeRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(service.enviarMensaje(id,request));}
 @DeleteMapping("/{id}/mensajes/{mensajeId}") @PreAuthorize("hasAuthority('Grupos:Ver')") public ResponseEntity<Void> eliminarMensaje(@PathVariable Long id,@PathVariable Long mensajeId){service.eliminarMensaje(id,mensajeId);return ResponseEntity.noContent().build();}
 @PostMapping @PreAuthorize("hasAuthority('Grupos:Crear')") public ResponseEntity<GrupoResponse> crear(@Valid @RequestBody GrupoRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.crear(conJefeUnidad(r)));}
 @PutMapping("/{id}") @PreAuthorize("hasAuthority('Grupos:Editar')") public GrupoResponse actualizar(@PathVariable Long id,@Valid @RequestBody GrupoRequest r){return service.actualizar(id,conJefeUnidad(r));}
 @PatchMapping("/{id}/estado") @PreAuthorize("hasAuthority('Grupos:Cambiar estado')") public GrupoResponse estado(@PathVariable Long id){return service.cambiarEstado(id);}
 @DeleteMapping("/{id}") @PreAuthorize("hasAuthority('Grupos:Eliminar')") public ResponseEntity<Void> eliminar(@PathVariable Long id){service.eliminar(id);return ResponseEntity.noContent().build();}
 @GetMapping("/{id}/miembros") @PreAuthorize("hasAuthority('Grupos:Ver')") public List<GrupoMiembroResponse> miembros(@PathVariable Long id){return service.listarMiembros(id);}
 @PutMapping("/{id}/miembros") @PreAuthorize("hasAuthority('Grupos:Editar')") public List<GrupoMiembroResponse> actualizarMiembros(@PathVariable Long id,@RequestBody GrupoMiembrosRequest request){return service.actualizarMiembros(id,request.miembroIds());}
 @GetMapping("/{id}/actividades") @PreAuthorize("hasAuthority('Grupos:Ver actividades')") public List<AuditLog> actividades(@PathVariable Long id){return service.actividades(id);}
 private GrupoRequest conJefeUnidad(GrupoRequest r){ var membresias=usuarioUnidades.findByUnidadId(r.unidadId()); Long jefe=membresias.stream().filter(x->x.getRol()!=null && "jefe de unidad".equalsIgnoreCase(x.getRol().getNombre())).map(x->x.getUsuario().getId()).findFirst().orElseThrow(()->new IllegalArgumentException("La unidad seleccionada no tiene un Jefe de Unidad asignado")); Set<Long> miembros=new LinkedHashSet<>(r.miembroIds()==null?List.of():r.miembroIds()); membresias.stream().map(x->x.getUsuario()).filter(ParticipantePolicy::puedeParticipar).map(x->x.getId()).forEach(miembros::add); miembros.add(jefe); return new GrupoRequest(r.nombre(),r.descripcion(),r.unidadId(),r.tipo(),r.icono(),r.color(),r.activo(),jefe,new ArrayList<>(miembros),r.permisoIds()); }
}
